const input = $input.first().json;
const body = input.body || input;

const event = body.event || '';
const status = body.status || (body.conversation && body.conversation.status) || '';
const meta = body.meta || (body.conversation && body.conversation.meta) || {};
const sender = meta.sender || body.sender || body.contact || {};
const assignee = meta.assignee || body.assignee || null;
const inboxId = body.inbox_id || (body.conversation && body.conversation.inbox_id) || null;
const convId = body.id || (body.conversation && body.conversation.id) || null;
const changed = body.changed_attributes || (body.conversation && body.conversation.changed_attributes) || {};

let digits = String(sender.phone_number || '').replace(/[^0-9]/g, '');
if (digits.startsWith('0') && digits.length === 10) digits = '27' + digits.slice(1);

// Chatwoot only exposes these conversation-level events to webhook
// subscriptions. assignee.changed is not subscribable in stock Chatwoot —
// agent assignment arrives as conversation_updated with
// changed_attributes.assignee_id (Rails dirty-tracking diff).
const RELEVANT = ['assignee_changed', 'conversation_updated', 'conversation_status_changed'];

const assigneeAttr = changed.assignee_id !== undefined ? changed.assignee_id : changed.assignee;
let assigneeBecame;
if (assigneeAttr !== undefined) {
  assigneeBecame = Array.isArray(assigneeAttr)
    ? assigneeAttr[1]
    : (assigneeAttr && typeof assigneeAttr === 'object' ? assigneeAttr.current_value : assigneeAttr);
}

let takeOver = null;
if (RELEVANT.includes(event)) {
  if (status === 'resolved' || status === 'closed') {
    takeOver = false;
  } else if (event === 'assignee_changed' || event === 'conversation_status_changed') {
    // Reopened: assigned -> human owns it again; unassigned -> Layla resumes.
    takeOver = !!assignee;
  } else {
    // conversation_updated: only sync when the assignee actually changed,
    // so unrelated updates (labels, snooze, custom attrs) never clear a
    // manually-set takeover. Legacy payloads without a diff fall back to
    // current assignee state.
    const hasDiff = changed && Object.keys(changed).length > 0;
    if (assigneeAttr !== undefined) takeOver = !!assigneeBecame;
    else if (!hasDiff) takeOver = !!assignee;
  }
}

if (takeOver === null || !digits) {
  return [{ json: { action: 'ignore', event, status, inbox_id: inboxId, conversation_id: convId } }];
}

return [{ json: {
  action: 'sync',
  phone: digits,
  take_over: takeOver,
  by: 'chatwoot:' + event,
  event,
  status,
  inbox_id: inboxId,
  conversation_id: convId,
}}];
